// Flat config. `next lint` was removed in Next 16, so ESLint is invoked directly
// (see the "lint" script) and this file is what it reads.
import nextCoreWebVitals from "eslint-config-next/core-web-vitals";
import nextTypescript from "eslint-config-next/typescript";

const config = [
  {
    // .next holds generated output and next-env.d.ts is regenerated by Next on
    // every dev/build — linting either reports on code nobody wrote.
    ignores: [".next/**", "next-env.d.ts", "coverage/**"],
  },
  ...nextCoreWebVitals,
  ...nextTypescript,
  {
    // Staged adoption. This codebase had no linter until now, so turning the
    // config on at full strength would have meant 11 errors fixed inside a
    // documentation change. These three are demoted to warnings so they stay
    // visible without blocking, and so that a genuinely new error — a broken
    // import, an a11y violation — still fails the run.
    //
    // Both groups are real and worth fixing, separately:
    //   no-explicit-any (7)        agent tool-call payloads in features/ask and
    //                              features/ingest. The honest type is unknown
    //                              plus a narrowing helper, not a rename.
    //   set-state-in-effect (3)    cascading renders in AskWorkspace, VaultView
    //   purity (1)                 and RunStatus. Fixing them changes runtime
    //                              behaviour, which needs its own PR.
    rules: {
      "@typescript-eslint/no-explicit-any": "warn",
      "react-hooks/set-state-in-effect": "warn",
      "react-hooks/purity": "warn",
    },
  },
];

export default config;
